"""Password hashing helpers (Werkzeug ships with Flask)."""
import hmac

from werkzeug.security import check_password_hash, generate_password_hash

_HASH_PREFIXES = ("scrypt:", "pbkdf2:")


def hash_senha(senha):
    return generate_password_hash(senha)


def is_hash(valor):
    return isinstance(valor, str) and valor.startswith(_HASH_PREFIXES)


def verificar_senha(senha_armazenada, candidata):
    """Constant-time check. Accepts legacy plaintext values so old databases keep working;
    callers re-hash on success (see is_hash)."""
    if not senha_armazenada:
        return False
    if is_hash(senha_armazenada):
        return check_password_hash(senha_armazenada, candidata)
    return hmac.compare_digest(senha_armazenada.encode(), candidata.encode())

