"""Data access for pedidos and itens_pedido."""
from config.constants import PRODUTO_DESCONHECIDO, STATUS_APROVADO, STATUS_CANCELADO, STATUS_PENDENTE
from database.connection import get_db
from middlewares.errors import ValidationError

_SQL_PEDIDOS_COM_ITENS = """
    SELECT p.id, p.usuario_id, p.status, p.total, p.criado_em,
           i.id AS item_id, i.produto_id, i.quantidade, i.preco_unitario,
           pr.id AS produto_existe, pr.nome AS produto_nome
    FROM pedidos p
    LEFT JOIN itens_pedido i ON i.pedido_id = p.id
    LEFT JOIN produtos pr ON pr.id = i.produto_id
    {where}
    ORDER BY p.id, i.id
"""


def _agrupar(rows):
    pedidos = {}
    for row in rows:
        pedido = pedidos.get(row["id"])
        if pedido is None:
            pedido = pedidos[row["id"]] = {
                "id": row["id"],
                "usuario_id": row["usuario_id"],
                "status": row["status"],
                "total": row["total"],
                "criado_em": row["criado_em"],
                "itens": [],
            }
        if row["item_id"] is not None:
            pedido["itens"].append({
                "produto_id": row["produto_id"],
                "produto_nome": row["produto_nome"] if row["produto_existe"] is not None else PRODUTO_DESCONHECIDO,
                "quantidade": row["quantidade"],
                "preco_unitario": row["preco_unitario"],
            })
    return list(pedidos.values())


def listar(usuario_id=None):
    if usuario_id is None:
        rows = get_db().execute(_SQL_PEDIDOS_COM_ITENS.format(where="")).fetchall()
    else:
        rows = get_db().execute(
            _SQL_PEDIDOS_COM_ITENS.format(where="WHERE p.usuario_id = ?"), (usuario_id,)
        ).fetchall()
    return _agrupar(rows)


def precificar_itens(itens):
    """Validates existence and stock of each item and returns the order total."""
    conn = get_db()
    total = 0
    for item in itens:
        produto = conn.execute(
            "SELECT nome, preco, estoque FROM produtos WHERE id = ?", (item["produto_id"],)
        ).fetchone()
        if produto is None:
            raise ValidationError("Produto " + str(item["produto_id"]) + " não encontrado")
        if produto["estoque"] < item["quantidade"]:
            raise ValidationError("Estoque insuficiente para " + produto["nome"])
        total = total + (produto["preco"] * item["quantidade"])
    return total


def criar(usuario_id, itens, total):
    """Atomic: order, items and stock decrements are committed together or not at all."""
    conn = get_db()
    with conn:
        pedido_id = conn.execute(
            "INSERT INTO pedidos (usuario_id, status, total) VALUES (?, ?, ?)",
            (usuario_id, STATUS_PENDENTE, total),
        ).lastrowid
