"""Request validation. Every function raises ValidationError (HTTP 400) on bad input."""
import re

from config.constants import (
    CATEGORIA_PADRAO,
    CATEGORIAS_VALIDAS,
    NOME_PRODUTO_MAX,
    NOME_PRODUTO_MIN,
    STATUS_PEDIDO_VALIDOS,
)
from middlewares.errors import ValidationError

_EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


def _is_number(valor):
    return isinstance(valor, (int, float)) and not isinstance(valor, bool)


def _is_int(valor):
    return isinstance(valor, int) and not isinstance(valor, bool)


def json_obrigatorio(dados):
    if not dados or not isinstance(dados, dict):
        raise ValidationError("Dados inválidos")
    return dados


def produto(dados):
    dados = json_obrigatorio(dados)
    if "nome" not in dados:
        raise ValidationError("Nome é obrigatório")
    if "preco" not in dados:
        raise ValidationError("Preço é obrigatório")
    if "estoque" not in dados:
        raise ValidationError("Estoque é obrigatório")

    nome = dados["nome"]
    descricao = dados.get("descricao", "")
    preco = dados["preco"]
    estoque = dados["estoque"]
    categoria = dados.get("categoria", CATEGORIA_PADRAO)

    if not isinstance(nome, str):
        raise ValidationError("Nome deve ser texto")
    if not isinstance(descricao, str):
        raise ValidationError("Descrição deve ser texto")
    if not _is_number(preco):
        raise ValidationError("Preço deve ser numérico")
    if not _is_int(estoque):
        raise ValidationError("Estoque deve ser um número inteiro")
    if preco < 0:
        raise ValidationError("Preço não pode ser negativo")
    if estoque < 0:
        raise ValidationError("Estoque não pode ser negativo")
    if len(nome) < NOME_PRODUTO_MIN:
        raise ValidationError("Nome muito curto")
    if len(nome) > NOME_PRODUTO_MAX:
        raise ValidationError("Nome muito longo")
    if categoria not in CATEGORIAS_VALIDAS:
        raise ValidationError("Categoria inválida. Válidas: " + str(CATEGORIAS_VALIDAS))

    return {"nome": nome, "descricao": descricao, "preco": preco, "estoque": estoque, "categoria": categoria}


def filtro_preco(valor, nome_parametro):
    if valor is None or valor == "":
        return None
    try:
        return float(valor)
    except ValueError:
        raise ValidationError(nome_parametro + " inválido") from None


def novo_usuario(dados):
    dados = json_obrigatorio(dados)
    nome = dados.get("nome", "")
    email = dados.get("email", "")
    senha = dados.get("senha", "")
    if not all(isinstance(valor, str) and valor for valor in (nome, email, senha)):
        raise ValidationError("Nome, email e senha são obrigatórios")
    if not _EMAIL_RE.match(email):
        raise ValidationError("Email inválido")
    return {"nome": nome, "email": email, "senha": senha}


def credenciais(dados):
    dados = dados if isinstance(dados, dict) else {}
    email = dados.get("email", "")
    senha = dados.get("senha", "")
    if not (isinstance(email, str) and email and isinstance(senha, str) and senha):
        raise ValidationError("Email e senha são obrigatórios")
    return email, senha


def novo_pedido(dados):
    dados = json_obrigatorio(dados)
    usuario_id = dados.get("usuario_id")
    itens = dados.get("itens", [])
    if not usuario_id:
        raise ValidationError("Usuario ID é obrigatório")
    if not _is_int(usuario_id):
        raise ValidationError("Usuario ID inválido")
    if not itens or not isinstance(itens, list):
        raise ValidationError("Pedido deve ter pelo menos 1 item")
    for item in itens:
        if not (isinstance(item, dict) and _is_int(item.get("produto_id"))
                and _is_int(item.get("quantidade")) and item["quantidade"] > 0):
            raise ValidationError("Item inválido: produto_id e quantidade (inteiro positivo) são obrigatórios")
    return usuario_id, [{"produto_id": item["produto_id"], "quantidade": item["quantidade"]} for item in itens]


def status_pedido(dados):
    dados = json_obrigatorio(dados)
    novo_status = dados.get("status", "")
    if novo_status not in STATUS_PEDIDO_VALIDOS:
        raise ValidationError("Status inválido")
    return novo_status


def consulta_sql(dados):
    dados = dados if isinstance(dados, dict) else {}
    sql = dados.get("sql", "")
    if not sql or not isinstance(sql, str):
        raise ValidationError("Query não informada")
    texto = sql.strip().rstrip(";").strip()
    if not texto.upper().startswith("SELECT") or ";" in texto:
        raise ValidationError("Apenas uma consulta SELECT é permitida")
    return texto

