    if b["status"] != n["status"]:
        issues.append(f'status {b["status"]} -> {n["status"]}')
    if b["keys"] != n["keys"]:
        issues.append(f'keys -{sorted(set(b["keys"] or []) - set(n["keys"] or []))} +{sorted(set(n["keys"] or []) - set(b["keys"] or []))}')
    if b["dados_keys"] != n["dados_keys"]:
        issues.append(f'dados -{sorted(set(b["dados_keys"] or []) - set(n["dados_keys"] or []))} +{sorted(set(n["dados_keys"] or []) - set(b["dados_keys"] or []))}')
    if b["erro"] != n["erro"]:
        issues.append(f'erro {b["erro"]!r} -> {n["erro"]!r}')
    if b["ctype"] != n["ctype"]:
        issues.append(f'ctype {b["ctype"]} -> {n["ctype"]}')
    if issues:
        diffs += 1
        print(f'{b["label"]:<28} ' + "; ".join(issues))
print(f"{len(base)} requests compared, {diffs} with differences")

